# region: fold
def fold(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: shape
def shape(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs[:-1]:
        acc = acc + v
        out.append(acc)
    return out

# region: digest
def digest(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: gather
def gather(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: emit
def emit(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return emit(gather(digest(intake(shape(fold(raw))))))

